pub(crate) async fn send_create_message_request<ContentT: AsRef<[u8]>>(
    &self,
    folder_id: Option<String>,
    content: ContentT,
) -> Result<Message, XpComGraphError> {
    let content = BASE64_STANDARD.encode(content);

    let body = OperationBody::Other {
        content_type: "text/plain".to_string(),
        body: content.as_bytes().to_vec(),
    };

    let base_url = self.base_api_url()?.to_string();

    let request = messages::Post::new(base_url, body);
    let message = self
        .send_request_json_response(request, Default::default())
        .await?;
